INSERT INTO series (id, slug, medium, years, sort_order, title_tr, title_en, meta_tr, meta_en, note_tr, note_en, cover_work_id, published) VALUES ('s_kivrim', 'kivrim', 'prints', '2023–2025', 1, 'Kıvrım', 'Fold', '4 iş, serigrafi', '4 works, screenprint', 'Aynı perdenin dört kez, farklı ışıkta baskıya alınmış hali. Her baskıda katman sayısı azalıyor; seri sonunda geriye yalnızca kıvrımın izi kalıyor.', 'The same curtain printed four times under changing light. Each print carries fewer layers than the last, until only the trace of the fold remains.', 'w2', 1);
INSERT INTO series (id, slug, medium, years, sort_order, title_tr, title_en, meta_tr, meta_en, note_tr, note_en, cover_work_id, published) VALUES ('s_esik', 'esik', 'paper', '2022–2024', 2, 'Eşik', 'Threshold', '4 iş, kağıt üzerine', '4 works, on paper', 'Bir odadan diğerine geçiş anını tutan kağıt işleri. Mürekkep ve pigment, eşiğin iki yanındaki iki farklı ışığı tek yüzeyde buluşturuyor.', 'Works on paper holding the moment of passing from one room to the next. Ink and pigment bring the two different lights on either side of the threshold onto one surface.', 'w7', 1);
INSERT INTO series (id, slug, medium, years, sort_order, title_tr, title_en, meta_tr, meta_en, note_tr, note_en, cover_work_id, published) VALUES ('s_oda', 'oda', 'paintings', '2021–2024', 3, 'Oda', 'Room', '3 iş, ketende yağlıboya', '3 works, oil on linen', 'Aynı odanın üç kez, üç ayrı ölçüde resmi. En genişi duvarın tamamını, en darı yalnızca pencere ile kapı arasındaki aralığı alıyor; ölçü değiştikçe odanın neye benzediği de değişiyor.', 'The same room painted three times at three different sizes. The widest takes in the whole wall, the narrowest only the gap between window and door; as the measure changes, so does what the room looks like.', 'w16', 1);
INSERT INTO works (id, slug, medium, series_id, year, sort_order, title_tr, title_en, caption_tr, caption_en, note_tr, note_en, width, height, slot, image_key, published) VALUES ('w14', 'uzun-sabah', 'paintings', NULL, '2026', 1, 'Uzun Sabah', 'The Long Morning', 'Ketende yağlıboya, 65 × 200 cm', 'Oil on linen, 65 × 200 cm', 'Sergiye adını veren resim. Duvarın tamamını tek bir yatay şeride sıkıştırıyor; ışık soldan sağa, sabahın iki saati boyunca ilerliyor.', 'The painting the exhibition takes its name from. It compresses the whole wall into a single horizontal band; the light moves left to right across two hours of morning.', 1000, 325, 'painting 65×200', NULL, 1);
INSERT INTO works (id, slug, medium, series_id, year, sort_order, title_tr, title_en, caption_tr, caption_en, note_tr, note_en, width, height, slot, image_key, published) VALUES ('w1', 'sabah-duvari', 'paintings', NULL, '2025', 2, 'Sabah Duvarı', 'Morning Wall', 'Ketende yağlıboya, 120 × 90 cm', 'Oil on linen, 120 × 90 cm', 'Kadıköy''deki atölyenin kuzey duvarı, sabah yedi ile dokuz arası. Aynı yüzeyi üç ay boyunca aynı saatte çalıştı; boya sabah ışığının duvarı ne kadar yavaş kat ettiğini kaydediyor. Katmanların hiçbiri tamamen kapatılmadı, bu yüzden ilk günün grisi son günün turuncusunun altından görünmeye devam ediyor.', 'The north wall of the Kadıköy studio, between seven and nine in the morning. She worked the same surface at the same hour for three months; the paint records how slowly the light crosses it. No layer was ever fully covered, so the grey of the first day still shows beneath the orange of the last.', 420, 560, 'painting 120×90', NULL, 1);
INSERT INTO works (id, slug, medium, series_id, year, sort_order, title_tr, title_en, caption_tr, caption_en, note_tr, note_en, width, height, slot, image_key, published) VALUES ('w2', 'kivrim-i', 'prints', 's_kivrim', '2025', 3, 'Kıvrım I', 'Fold I', 'Serigrafi, 5 baskı, 50 × 40 cm', 'Screenprint, ed. 5, 50 × 40 cm', 'Serinin ilk baskısı: perde henüz katı, kıvrım keskin. Beş katman serigrafi, en açık tondan en koyuya doğru.', 'The first print of the series: the curtain still solid, the fold still sharp. Five screenprinted layers, lightest tone to darkest.', 400, 500, 'print 50×40', NULL, 1);
INSERT INTO works (id, slug, medium, series_id, year, sort_order, title_tr, title_en, caption_tr, caption_en, note_tr, note_en, width, height, slot, image_key, published) VALUES ('w3', 'kivrim-ii', 'prints', 's_kivrim', '2024', 4, 'Kıvrım II', 'Fold II', 'Serigrafi, 5 baskı, 50 × 40 cm', 'Screenprint, ed. 5, 50 × 40 cm', 'İkinci baskıda katman sayısı dörde iniyor; kumaşın ağırlığı yerini ışığa bırakıyor.', 'In the second print the layers drop to four; the weight of the fabric gives way to light.', 420, 510, 'print 50×40', NULL, 1);
INSERT INTO works (id, slug, medium, series_id, year, sort_order, title_tr, title_en, caption_tr, caption_en, note_tr, note_en, width, height, slot, image_key, published) VALUES ('w4', 'kivrim-iii', 'prints', 's_kivrim', '2024', 5, 'Kıvrım III', 'Fold III', 'Serigrafi, 5 baskı, 50 × 40 cm', 'Screenprint, ed. 5, 50 × 40 cm', 'Üçüncü baskı yalnızca üç geçişle yapıldı. Kıvrımın kendisi değil, kıvrımın gölgesi taşınıyor.', 'The third print was pulled in only three passes. What carries over is not the fold but its shadow.', 430, 520, 'print 50×40', NULL, 1);
INSERT INTO works (id, slug, medium, series_id, year, sort_order, title_tr, title_en, caption_tr, caption_en, note_tr, note_en, width, height, slot, image_key, published) VALUES ('w5', 'kivrim-iv', 'prints', 's_kivrim', '2023', 6, 'Kıvrım IV', 'Fold IV', 'Serigrafi, 5 baskı, 50 × 40 cm', 'Screenprint, ed. 5, 50 × 40 cm', 'Serinin sonu: tek geçiş, tek ton. Perdeden kalan şey bir kenar izi.', 'The end of the series: one pass, one tone. What remains of the curtain is the trace of an edge.', 420, 516, 'print 50×40', NULL, 1);
INSERT INTO works (id, slug, medium, series_id, year, sort_order, title_tr, title_en, caption_tr, caption_en, note_tr, note_en, width, height, slot, image_key, published) VALUES ('w15', 'dar-aralik', 'paper', NULL, '2025', 7, 'Dar Aralık', 'Narrow Gap', 'Kağıt üzerine pigment, 56 × 18 cm', 'Pigment on paper, 56 × 18 cm', 'Pencere ile duvarın arasında kalan on sekiz santimlik boşluk. Kağıdın uzunluğu, bakışın yukarıdan aşağı inmesi için seçildi.', 'The eighteen centimetres left between the window and the wall. The length of the sheet was chosen to make the eye travel from top to bottom.', 270, 840, 'drawing 56×18', NULL, 1);
INSERT INTO works (id, slug, medium, series_id, year, sort_order, title_tr, title_en, caption_tr, caption_en, note_tr, note_en, width, height, slot, image_key, published) VALUES ('w6', 'legendeki-su', 'paintings', NULL, '2024', 8, 'Leğendeki Su', 'Water in a Basin', 'Ketende yağlıboya, 60 × 75 cm', 'Oil on linen, 60 × 75 cm', 'Emaye bir leğende duran su. Yüzey her hareket ettiğinde odanın tavanını farklı bir biçimde geri veriyor; resim bu geri dönüşlerden birini seçiyor.', 'Water held in an enamel basin. Each time the surface moves it returns the ceiling differently; the painting settles on one of those returns.', 560, 442, 'painting 60×75', NULL, 1);
INSERT INTO works (id, slug, medium, series_id, year, sort_order, title_tr, title_en, caption_tr, caption_en, note_tr, note_en, width, height, slot, image_key, published) VALUES ('w7', 'esik-i-perde', 'paper', 's_esik', '2024', 9, 'Eşik I — Perde', 'Threshold I — Curtain', 'Kağıt üzerine pigment, 42 × 30 cm', 'Pigment on paper, 42 × 30 cm', 'Eşik serisinin açılışı. Perde yarı çekili, iki odanın ışığı tek kağıtta üst üste biniyor.', 'The opening of the Threshold series. The curtain half drawn, the light of two rooms overlapping on one sheet.', 420, 570, 'drawing 42×30', NULL, 1);
INSERT INTO works (id, slug, medium, series_id, year, sort_order, title_tr, title_en, caption_tr, caption_en, note_tr, note_en, width, height, slot, image_key, published) VALUES ('w8', 'esik-ii', 'paper', 's_esik', '2023', 10, 'Eşik II', 'Threshold II', 'Kağıt üzerine mürekkep, 30 × 24 cm', 'Ink on paper, 30 × 24 cm', 'Kapı boşluğunun ölçüsü, mürekkebin kağıda yayılma hızına bırakılmış.', 'The measure of the doorway is left to the speed at which ink spreads on paper.', 410, 500, 'drawing 30×24', NULL, 1);
INSERT INTO works (id, slug, medium, series_id, year, sort_order, title_tr, title_en, caption_tr, caption_en, note_tr, note_en, width, height, slot, image_key, published) VALUES ('w9', 'esik-iii', 'paper', 's_esik', '2023', 11, 'Eşik III', 'Threshold III', 'Kağıt üzerine mürekkep, 30 × 24 cm', 'Ink on paper, 30 × 24 cm', 'Aynı eşik, akşam. Pigment bu kez daha az su ile karıştırıldı; kenarlar sertleşti.', 'The same threshold, at dusk. Here the pigment was mixed with less water; the edges hardened.', 410, 505, 'drawing 30×24', NULL, 1);
INSERT INTO works (id, slug, medium, series_id, year, sort_order, title_tr, title_en, caption_tr, caption_en, note_tr, note_en, width, height, slot, image_key, published) VALUES ('w10', 'esik-iv', 'paper', 's_esik', '2022', 12, 'Eşik IV', 'Threshold IV', 'Kağıt üzerine mürekkep ve pigment, 30 × 24 cm', 'Ink and pigment on paper, 30 × 24 cm', 'Serinin en küçük işi ve en uzun süre çalışılanı; kağıt dört kez ıslatıldı.', 'The smallest work in the series and the longest worked; the paper was wetted four times.', 415, 500, 'drawing 30×24', NULL, 1);
INSERT INTO works (id, slug, medium, series_id, year, sort_order, title_tr, title_en, caption_tr, caption_en, note_tr, note_en, width, height, slot, image_key, published) VALUES ('w16', 'oda-i-genis', 'paintings', 's_oda', '2024', 13, 'Oda I — Geniş', 'Room I — Wide', 'Ketende yağlıboya, 90 × 220 cm', 'Oil on linen, 90 × 220 cm', 'Odanın en geniş hali: duvar, pencere ve kapı tek bir yatay okumada. Boya serinin en incesi bu resimde.', 'The room at its widest: wall, window and door in a single horizontal reading. The paint is thinnest here.', 1100, 450, 'painting 90×220', NULL, 1);
INSERT INTO works (id, slug, medium, series_id, year, sort_order, title_tr, title_en, caption_tr, caption_en, note_tr, note_en, width, height, slot, image_key, published) VALUES ('w17', 'oda-ii-kare', 'paintings', 's_oda', '2023', 14, 'Oda II — Kare', 'Room II — Square', 'Ketende yağlıboya, 100 × 100 cm', 'Oil on linen, 100 × 100 cm', 'Aynı oda kareye alındığında pencere merkeze düşüyor, duvar kenarlara doğru kayboluyor.', 'Squared off, the same room puts the window at the centre and lets the wall fall away at the edges.', 600, 600, 'painting 100×100', NULL, 1);
INSERT INTO works (id, slug, medium, series_id, year, sort_order, title_tr, title_en, caption_tr, caption_en, note_tr, note_en, width, height, slot, image_key, published) VALUES ('w18', 'oda-iii-dar', 'paintings', 's_oda', '2021', 15, 'Oda III — Dar', 'Room III — Narrow', 'Ketende yağlıboya, 130 × 45 cm', 'Oil on linen, 130 × 45 cm', 'Serinin son resmi yalnızca pencere ile kapı arasındaki aralığı tutuyor; oda artık dikey bir şerit.', 'The last painting in the series holds only the gap between window and door; the room is now a vertical strip.', 315, 910, 'painting 130×45', NULL, 1);
INSERT INTO works (id, slug, medium, series_id, year, sort_order, title_tr, title_en, caption_tr, caption_en, note_tr, note_en, width, height, slot, image_key, published) VALUES ('w11', 'gec-isik', 'paintings', NULL, '2024', 16, 'Geç Işık', 'Late Light', 'Ketende yağlıboya, 150 × 110 cm', 'Oil on linen, 150 × 110 cm', 'Günün son yirmi dakikası. Turuncunun altında kalan gri, ilk oturumdan beri hiç kapatılmadı.', 'The last twenty minutes of the day. The grey beneath the orange has stayed uncovered since the first sitting.', 430, 568, 'painting 150×110', NULL, 1);
INSERT INTO works (id, slug, medium, series_id, year, sort_order, title_tr, title_en, caption_tr, caption_en, note_tr, note_en, width, height, slot, image_key, published) VALUES ('w19', 'kapi-boyu', 'paintings', NULL, '2022', 17, 'Kapı Boyu', 'Door Height', 'Ketende yağlıboya, 190 × 105 cm', 'Oil on linen, 190 × 105 cm', 'Ölçü bir kapıdan alındı. Resim duvara asıldığında insan boyuyla aynı hizada duruyor.', 'The measure was taken from a door. Hung on the wall, the painting stands at the height of a person.', 420, 760, 'painting 190×105', NULL, 1);
INSERT INTO works (id, slug, medium, series_id, year, sort_order, title_tr, title_en, caption_tr, caption_en, note_tr, note_en, width, height, slot, image_key, published) VALUES ('w12', 'kirec', 'paintings', NULL, '2022', 18, 'Kireç', 'Lime', 'Ketende yağlıboya, 90 × 90 cm', 'Oil on linen, 90 × 90 cm', 'Badanalı bir duvarın yakın planı. Kare format, bakışın yüzeyden başka gidecek yeri olmasın diye seçildi.', 'A whitewashed wall, close up. The square format was chosen so the eye has nowhere to go but the surface.', 500, 500, 'painting 90×90', NULL, 1);
INSERT INTO works (id, slug, medium, series_id, year, sort_order, title_tr, title_en, caption_tr, caption_en, note_tr, note_en, width, height, slot, image_key, published) VALUES ('w20', 'kenar-notu', 'paper', NULL, '2022', 19, 'Kenar Notu', 'Marginal Note', 'Kağıt üzerine mürekkep, 10 × 14 cm', 'Ink on paper, 10 × 14 cm', 'Avuç içi kadar bir çalışma. Büyük resimlerin kenarında tutulan notlardan biri; rengin nerede duracağını burada deniyor.', 'A study the size of a palm. One of the notes kept alongside the large paintings, where she tries out where a colour should stop.', 560, 400, 'drawing 10×14', NULL, 1);
INSERT INTO works (id, slug, medium, series_id, year, sort_order, title_tr, title_en, caption_tr, caption_en, note_tr, note_en, width, height, slot, image_key, published) VALUES ('w13', 'havza', 'prints', NULL, '2022', 20, 'Havza', 'Basin', 'Litografi, 12 baskı, 66 × 48 cm', 'Lithograph, ed. 12, 66 × 48 cm', 'Litografi taşı üzerinde çalışılmış tek iş. Havza, leğendeki suyun büyütülmüş hali olarak düşünüldü.', 'The only work drawn on lithographic stone. The basin was conceived as an enlargement of the water in the bowl.', 560, 415, 'print 66×48', NULL, 1);
INSERT INTO works (id, slug, medium, series_id, year, sort_order, title_tr, title_en, caption_tr, caption_en, note_tr, note_en, width, height, slot, image_key, published) VALUES ('w21', 'sarnic', 'prints', NULL, '2020', 21, 'Sarnıç', 'Cistern', 'Gravür, 8 baskı, 40 × 70 cm', 'Etching, ed. 8, 40 × 70 cm', 'Bir sarnıcın su seviyesi. Hiçbir seriye girmeyen tek gravür; plaka bir daha kullanılmadı.', 'The water level in a cistern. The only etching that belongs to no series; the plate was never used again.', 700, 400, 'print 40×70', NULL, 1);
INSERT INTO exhibitions (id, year, sort_order, title_tr, title_en, venue_tr, venue_en, kind_tr, kind_en, note_tr, note_en, url, image_key, published) VALUES ('e1', '2026', 1, 'Uzun Sabah', 'The Long Morning', 'Galeri Nev, İstanbul', 'Galeri Nev, Istanbul', 'Kişisel sergi', 'Solo exhibition', 'Üç yıl boyunca aynı duvarın önünde yapılmış on dört resim, sergide sabahın saatlerine göre sıralandı. Salonun perdeleri gün boyunca açık bırakıldı; işler kendi konularının ışığı altında görüldü.', 'Fourteen paintings made in front of the same wall over three years, hung in the order of the morning hours. The gallery curtains stayed open all day, so the works were seen under the light they describe.', '#', NULL, 1);
INSERT INTO exhibitions (id, year, sort_order, title_tr, title_en, venue_tr, venue_en, kind_tr, kind_en, note_tr, note_en, url, image_key, published) VALUES ('e2', '2025', 2, 'Yüzeye Dair', 'On Surface', 'Zilberman, İstanbul', 'Zilberman, Istanbul', 'Grup sergisi', 'Group exhibition', 'Yedi sanatçının yüzey kavramı üzerine bir araya geldiği sergide Özkan, kağıt işlerinden oluşan bir duvar kurdu.', 'A show bringing seven artists together around the idea of surface, where Özkan built a wall entirely of works on paper.', '#', NULL, 1);
INSERT INTO exhibitions (id, year, sort_order, title_tr, title_en, venue_tr, venue_en, kind_tr, kind_en, note_tr, note_en, url, image_key, published) VALUES ('e3', '2024', 3, 'Kıvrım', 'Fold', 'Hangar, Lizbon', 'Hangar, Lisbon', 'Konuk sanatçı sergisi', 'Residency show', 'Üç aylık konuk sanatçı programının sonunda üretilen serigrafi serisi ilk kez burada, üretildikleri atölyenin içinde gösterildi.', 'The screenprint series made during a three-month residency, shown for the first time inside the workshop where it was printed.', '#', NULL, 1);
INSERT INTO exhibitions (id, year, sort_order, title_tr, title_en, venue_tr, venue_en, kind_tr, kind_en, note_tr, note_en, url, image_key, published) VALUES ('e4', '2023', 4, 'İki Oda', 'Two Rooms', 'Kunstraum Neukölln, Berlin', 'Kunstraum Neukölln, Berlin', 'İkili sergi', 'Two-person exhibition', 'Heykeltıraş Lene Voigt ile ortak sergi: iki oda, iki ışık, aralarında tek bir eşik.', 'A shared exhibition with the sculptor Lene Voigt: two rooms, two lights, a single threshold between them.', '#', NULL, 1);
INSERT INTO cv_entries (id, year, sort_order, title_tr, title_en, kind, url, published) VALUES ('cv1', '2026', 1, 'Uzun Sabah — Galeri Nev, İstanbul', 'The Long Morning — Galeri Nev, Istanbul', 'solo', '#', 1);
