INSERT INTO cv_entries (id, year, sort_order, title_tr, title_en, kind, url, published) VALUES ('cv6', '2023', 6, 'İki Oda — Kunstraum Neukölln, Berlin', 'Two Rooms — Kunstraum Neukölln, Berlin', 'group', '#', 1);
INSERT INTO cv_entries (id, year, sort_order, title_tr, title_en, kind, url, published) VALUES ('cv7', '2023', 7, 'Kağıt İşleri — K2, İzmir', 'Works on Paper — K2, Izmir', 'solo', '#', 1);
INSERT INTO cv_entries (id, year, sort_order, title_tr, title_en, kind, url, published) VALUES ('cv8', '2022', 8, 'Baskı Günleri — Kasa Galeri, İstanbul', 'Print Days — Kasa Galeri, Istanbul', 'group', '#', 1);
INSERT INTO cv_entries (id, year, sort_order, title_tr, title_en, kind, url, published) VALUES ('cv9', '2021', 9, 'Yakın Ölçek — Halka Sanat, İstanbul', 'Close Scale — Halka Sanat, Istanbul', 'group', '#', 1);
INSERT INTO cv_entries (id, year, sort_order, title_tr, title_en, kind, url, published) VALUES ('cv10', '2021', 10, 'Oda Işığı — Torun, Ankara', 'Room Light — Torun, Ankara', 'group', '#', 1);
INSERT INTO cv_entries (id, year, sort_order, title_tr, title_en, kind, url, published) VALUES ('cv11', '2020', 11, 'Başlangıç Katmanı — Mimar Sinan GSÜ, İstanbul', 'First Layer — Mimar Sinan FAU, Istanbul', 'group', '#', 1);
INSERT INTO cv_entries (id, year, sort_order, title_tr, title_en, kind, url, published) VALUES ('cv12', '2019', 12, 'Genç Resim — Akbank Sanat, İstanbul', 'Young Painting — Akbank Sanat, Istanbul', 'group', '#', 1);
INSERT INTO pages (key, data) VALUES ('about', '{"portraitSlot":{"tr":"atölye portresi","en":"studio portrait"},"portraitKey":null,"lead":{"tr":"Yeşim Özkan İstanbul''da yaşıyor ve çalışıyor.","en":"Yeşim Özkan lives and works in Istanbul."},"facts":[{"label":{"tr":"Eğitim","en":"Education"},"a":{"tr":"MFA Resim, Mimar Sinan","en":"MFA Painting, Mimar Sinan"},"b":{"tr":"Lisans Resim, Dokuz Eylül","en":"BA Painting, Dokuz Eylül"}},{"label":{"tr":"Konuk sanatçı","en":"Residencies"},"a":{"tr":"Hangar, Lizbon — 2024","en":"Hangar, Lisbon — 2024"},"b":{"tr":"Halka Sanat, İstanbul — 2021","en":"Halka Sanat, Istanbul — 2021"}},{"label":{"tr":"Basın","en":"Press"},"a":{"tr":"Argonotlar, 2025","en":"Argonotlar, 2025"},"b":{"tr":"Unlimited, 2023","en":"Unlimited, 2023"}}],"blocks":[{"type":"text","paragraphs":[{"tr":"Resimleri çok sıradan yüzeylerin uzun süreli gözleminden doğuyor: geç ışıkta bir duvar, leğende duran su, bir perdenin kıvrımı. Ketende ince yağlıboya ve pigment katmanlarıyla çalışıyor; her geçişin izini kısmen görünür bırakıyor, böylece resim kendi yapılışının hafızasını koruyor.","en":"Her paintings begin with sustained observation of very ordinary surfaces — a wall in late light, water held in a basin, the fold of a curtain. Working in thin layers of oil and pigment on linen, she lets each pass stay partly visible, so the finished picture keeps the memory of its own making."},{"tr":"Son işleri resimle kağıt arasında gidip geliyor ve ikisini tek bir pratik olarak ele alıyor: desenler bir rengi netleştiriyor, resimler deseni yeniden atmosfere çeviriyor. Ölçek tercihen mahrem kalıyor.","en":"Recent bodies of work move between painting and paper, treating the two as one continuous practice: drawings clarify a colour, paintings return the drawing to atmosphere. Scale stays intimate by choice."}]},{"type":"image","imageKey":null,"ratio":1.49,"caption":{"tr":"Kadıköy''deki atölye, kuzey penceresi, 2025","en":"The Kadıköy studio, north window, 2025"}},{"type":"pair","imageKeyA":null,"ratioA":0.8,"imageKeyB":null,"ratioB":0.8,"caption":{"tr":"Solda pigment denemeleri, sağda ilk katman sonrası bekleyen ketenler","en":"Pigment tests, left; linens resting after the first layer, right"}},{"type":"quote","quote":{"tr":"Bir yüzeyi yeterince uzun süre izlerseniz, resim kendi kendine bir konu buluyor.","en":"If you watch a surface long enough, the painting finds a subject on its own."},"by":{"tr":"Argonotlar söyleşisi, 2025","en":"Interview, Argonotlar, 2025"}},{"type":"text","paragraphs":[{"tr":"Mimar Sinan Güzel Sanatlar Üniversitesi''nde resim okudu; İstanbul, İzmir, Berlin ve Lizbon''da sergiler açtı. İşleri Türkiye ve Avrupa''daki özel koleksiyonlarda yer alıyor.","en":"She studied painting at Mimar Sinan Fine Arts University and has exhibited in Istanbul, Izmir, Berlin and Lisbon. Her work is held in private collections in Turkey and Europe."}]},{"type":"image","imageKey":null,"ratio":1.77,"caption":{"tr":"Kıvrım serisinin baskı günleri, Hangar, Lizbon, 2024","en":"Printing days for the Fold series, Hangar, Lisbon, 2024"}}]}');
INSERT INTO pages (key, data) VALUES ('contact', '{"lead":{"tr":"Sergi, temsil ve atölye ziyaretleri için.","en":"For exhibitions, representation and studio visits."},"note":{"tr":"Mevcut işlerin listesi ve fiyatlar talep üzerine gönderilir. Atölye ziyaretleri Kadıköy''de, randevu ile.","en":"A list of available works and prices is sent on request. Studio visits in Kadıköy, by appointment."},"rows":[{"label":{"tr":"E-posta","en":"Email"},"value":"studio@yesimozkan.com","href":"mailto:studio@yesimozkan.com"},{"label":{"tr":"Instagram","en":"Instagram"},"value":"@yesimozkan","href":"https://instagram.com/yesimozkan"},{"label":{"tr":"Temsil","en":"Representation"},"value":"Galeri Nev, İstanbul","href":"#"},{"label":{"tr":"Atölye","en":"Studio"},"value":"Kadıköy, İstanbul","href":"#"}]}');
